+pub(crate) fn dialog_gcd_k2_pair_copy_compressed_block_to_raw(
+    b: &mut B,
+    compressed_block: &[QubitId],
+    raw_block: &[QubitId],
+    steps: usize,
+) {
+    assert_eq!(compressed_block.len(), DIALOG_GCD_HIGH_TAIL_ALIAS_BLOCK_BITS);
+    assert_eq!(raw_block.len(), 6);
+    assert!((1..=2).contains(&steps));
+    let swap_host = dialog_gcd_apply_replay_swap_host_enabled();
+    if steps == 1 {
+        let raw_encoded = [raw_block[0], raw_block[1], raw_block[4]];
+        for (&c, &r) in compressed_block.iter().take(3).zip(raw_encoded.iter()) {
+            if swap_host {
+                b.swap(c, r);
+            } else {
+                b.cx(c, r);
+            }
+        }
+        return;
+    }
+    let raw_encoded = [raw_block[1], raw_block[4], raw_block[2], raw_block[3], raw_block[5]];
+    for (&c, &r) in compressed_block.iter().zip(raw_encoded.iter()) {
+        if swap_host {
+            b.swap(c, r);
+        } else {
+            b.cx(c, r);
+        }
+    }
+    let core = dialog_gcd_k2_pair_core(raw_block);
+    emit_dialog_gcd_k2_pair_core_encoder_inverse(b, &core);

+    fn new_count_only() -> Self {
+        let mut b = Self::new();
+        b.count_only = true;
+        b.fiat_hash = Self::fiat_hash_from_env();
+        b
+    }
+    fn fiat_hash_from_env() -> Option<Shake256> {
+        let ops_len = std::env::var("POINT_ADD_HASH_OPS_LEN")
+            .ok()
+            .and_then(|s| s.parse::<u64>().ok())?;
+        let mut hasher = Shake256::default();
+        hasher.update(b"quantum_ecc-fiat-shamir-v2");
+        hasher.update(&ops_len.to_le_bytes());
+        Some(hasher)
+    }
+    pub(crate) fn update_fiat_hash_op(hasher: &mut Shake256, op: &Op) {
+        hasher.update(&[op.kind as u8]);
+        hasher.update(&op.q_control2.0.to_le_bytes());
+        hasher.update(&op.q_control1.0.to_le_bytes());
+        hasher.update(&op.q_target.0.to_le_bytes());
+        hasher.update(&op.c_target.0.to_le_bytes());
+        hasher.update(&op.c_condition.0.to_le_bytes());
+        hasher.update(&op.r_target.0.to_le_bytes());
+    }
+    pub(crate) fn clone_fiat_hash(&self) -> Option<Shake256> {
+        self.fiat_hash.clone()
+    }
+    fn push_op(&mut self, op: Op) {
+        self.counted_ops += 1;
+        self.counted_kind_ops[op.kind as usize] += 1;
+        self.counted_phase_kind_ops[op.kind as usize] += 1;
+        if let Some(hasher) = &mut self.fiat_hash {
+            Self::update_fiat_hash_op(hasher, &op);
+        }
+        if !self.count_only {
+            self.ops.push(op);
+        }

+fn configure_sub1000_trailmix_route() {
+    set_default_env("TRAILMIX_THIN_SCHEDULE", "1");
+    set_default_env("TRAILMIX_THIN_SEED", "278");
+    set_default_env("TRAILMIX_THIN_MARGIN", "0");
+    set_default_env("TRAILMIX_THIN_VALIDATE", "500000");
+    set_default_env("TRAILMIX_COUNTER_W", "8");
+    set_default_env("TRAILMIX_Q_CAP", "20");
+    set_default_env("TRAILMIX_SROT_W", "5");

+pub fn build_builder() -> crate::point_add::B {
+    configure_sub1000_trailmix_route();
+
+    let mut circ = circuit::Circuit::new();
+    circ.set_section("trailmix_shrunken_pz");
+    let mut tx = circ.alloc_qreg_bits("tx", 256);
+    let mut ty = circ.alloc_qreg_bits("ty", 256);
+    let ox: Vec<circuit::Cbit> = (0..256).map(|_| circ.alloc_input_bit()).collect();
+    let oy: Vec<circuit::Cbit> = (0..256).map(|_| circ.alloc_input_bit()).collect();
+
+    ec::point_add::ec_add_inplace_shrunken_pz(&mut circ, &mut tx, &mut ty, &ox, &oy);
+
+    let mut out = std::mem::take(&mut tx);
+    out.extend(std::mem::take(&mut ty));
+    let out = circ.defragment(out);
+    let tail_q0 = out[0].id();
+    let tail_q1 = out[1].id();
+    circ.declare_registers(&out[..256], &out[256..512], &ox, &oy);

+    if let Some(nonce) = std::env::var("TRAILMIX_TAIL_NONCE")
+        .ok()
+        .and_then(|s| s.parse::<u64>().ok())
+    {
+        circ.set_section("trailmix_tail_nonce");
+        for i in 0..TRAILMIX_TAIL_NONCE_BITS {
+            let q = if (nonce >> i) & 1 == 1 {
+                &out[1]
+            } else {
+                &out[0]
+            };
+            circ.x(q);
+            circ.x(q);
+        }
+    }
